const kpis = JSON.parse(inputData.kpisJson || '[]');
const ragColor = { green: '#16a34a', amber: '#d97706', red: '#dc2626' };
const ragEmoji = { green: '🟢', amber: '🟡', red: '🔴' };

const rows = kpis.map(k =>
  `<tr><td style='padding:10px;border-bottom:1px solid #e2e8f0'>${k.label}</td><td style='padding:10px;text-align:center;border-bottom:1px solid #e2e8f0;font-weight:bold'>${k.value}</td><td style='padding:10px;text-align:center;border-bottom:1px solid #e2e8f0;color:#64748b'>${k.target}</td><td style='padding:10px;text-align:center;border-bottom:1px solid #e2e8f0'><span style='color:${ragColor[k.rag]}'>${ragEmoji[k.rag]} ${k.rag.charAt(0).toUpperCase() + k.rag.slice(1)}</span></td></tr>`
).join('');

const html = `<!DOCTYPE html><html lang='en'><body style='font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;color:#1e293b'><div style='background:linear-gradient(135deg,#1e3a5f,#0ea5e9);padding:24px;border-radius:12px 12px 0 0;color:white'><h1 style='margin:0;font-size:20px'>📊 Weekly KPI Digest</h1><p style='margin:4px 0 0;opacity:0.85;font-size:13px'>Week of ${inputData.weekOf}</p></div><div style='border:1px solid #e2e8f0;border-top:none;padding:24px;border-radius:0 0 12px 12px'><p>Hi ${inputData.recipientName},</p><p>Here is your weekly KPI summary for the period ending <strong>${inputData.weekOf}</strong>:</p><table style='width:100%;border-collapse:collapse;font-size:13px;margin:16px 0'><thead><tr style='background:#f8fafc'><th style='padding:10px;text-align:left;border-bottom:2px solid #e2e8f0'>KPI</th><th style='padding:10px;text-align:center;border-bottom:2px solid #e2e8f0'>Value</th><th style='padding:10px;text-align:center;border-bottom:2px solid #e2e8f0'>Target</th><th style='padding:10px;text-align:center;border-bottom:2px solid #e2e8f0'>Status</th></tr></thead><tbody>${rows}</tbody></table><div style='text-align:center;margin-top:24px'><a href='https://YOUR_ISC_DOMAIN/' style='background:#0ea5e9;color:white;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold'>View Full Dashboard →</a></div><p style='color:#94a3b8;font-size:12px;margin-top:24px'>You receive this digest because you have an active ISC account. Sent every Monday.</p></div></body></html>`;

return { html };
